# Product claims, prior cash and explicitly modeled terminal recovery tails.
if(!exists('estimate_open_workout_lgd'))library(creditratingsystem)
run_structured_workout<-function(data=NULL,verify_reference=TRUE){
 if(is.null(data))data<-jsonlite::fromJSON(system.file('extdata/structured_workout.json',package='creditratingsystem'),simplifyVector=FALSE);out<-list();model<-data$residual_model
 for(product in names(data$variants)){
 case<-data$variants[[product]];ead<-case$ead;eid<-case$episode$episode_id;date<-case$default_date;defaults<-list(list(episode_id=eid,entity_id=case$subject_id,default_at=date,known_at=date,ead=ead,currency='EUR'));flows<-lapply(case$cashflows,function(f)list(cashflow_id=f$cashflow_id,episode_id=eid,cashflow_at=f$cashflow_date,known_at=f$known_at,amount=f$amount,kind='recovery',currency='EUR'));linked<-build_recovery_episodes(defaults,flows,cures=list(),evaluation_cutoff='2024-03-15')$value;recovery<-discount_recoveries(case$cashflows,case$discount_curve,case$fx_contract,default_date=date,evaluation_cutoff='2024-05-01',reporting_currency='EUR');observed_closed<-all(vapply(case$episode[c('resolution_date','resolution_known_at')],function(x)is.character(x)&&length(x)==1L&&x<='2024-05-01',logical(1)));closed<-workout_lgd(ead,recovery,episode_status=if(observed_closed)'CLOSED'else'OPEN',default_date=date,evaluation_cutoff='2024-05-01',currency='EUR')$value;known<-discount_recoveries(case$cashflows,case$discount_curve,case$fx_contract,default_date=date,evaluation_cutoff='2024-03-15',reporting_currency='EUR');incomplete<-workout_lgd(ead,known,episode_status='OPEN',default_date=date,evaluation_cutoff='2024-03-15',currency='EUR')$value
 openargs<-list(episodes=list(case$episode),cashflows=case$cashflows,fitted_recovery_model=model,X=matrix(numeric(),1,0),valuation_contracts=list(case$valuation),future_cost_cashflows=list(),feature_order=character(),expected_target=data$target,stage_spec=data$stage_spec,as_of='2024-03-15',currency='EUR',extrapolation='parametric');projected<-do.call(estimate_open_workout_lgd,openargs)$value;unknown<-openargs;unknown$valuation_contracts[[1]]['tail_discount_factor']<-list(NULL);unknown$valuation_contracts[[1]]['tail_assumption_reference']<-list(NULL);unidentified<-do.call(estimate_open_workout_lgd,unknown)$value
 conditional<-if(!observed_closed)NULL else event_conditioned_loss(list(list(state_id='survive',events=list(claim_default=FALSE),probability=.5,conditional_loss=0),list(state_id='default',events=list(claim_default=TRUE),probability=.5,conditional_loss=closed$economic_loss)),event_names='claim_default',currency='EUR',probability_measure='PHYSICAL')$value;treatment<-do.call(evaluate_treatment_candidates,case$treatment_input)$value;invalid<-case$treatment_input;invalid$treatment_candidates[[1]]$eligibility_status<-'INELIGIBLE';ineligible<-do.call(evaluate_treatment_candidates,invalid)$value
 if(product=='COUNTERPARTY_EXPOSURE')exposure<-list(applicability='NOT_APPLICABLE',method='ead.exposure_schedule',reason='Signed netting, collateral and margin-period closeout are not a drawn-loan schedule. The counterparty_credit_products recipe executes aggregate_netting_set_exposure, simulate_collateral_margin and closeout_exposure_at_default for this mechanism.')else {exposure_args<-case$exposure_input;exposure_args$annual_interest_rates<-unlist(exposure_args$annual_interest_rates);exposure_args$period_end_dates<-unlist(exposure_args$period_end_dates);exposure<-do.call(exposure_schedule,exposure_args)$value}
 out[[product]]<-list(linked_known_cashflows=linked,realized_recovery=recovery$value,closed_workout=closed,known_recovery=known$value,incomplete_workout=incomplete,projected_workout=projected,unidentified_tail=unidentified,event_conditioned_loss=conditional,treatment=treatment,ineligible_treatment=ineligible,exposure=exposure)
 }
 if(verify_reference){mean_positive<-sqrt(.25*.75)*exp((log(3)/2)^2/2);mean_ratio<-(1+mean_positive)/3;for(product in names(out)){r<-out[[product]];case<-data$variants[[product]];expected<-case$ead-case$past-case$terminal;stopifnot(abs(r$closed_workout$economic_loss-expected)<1e-10,is.null(r$incomplete_workout$economic_lgd));p<-r$projected_workout$episodes[[1]];stopifnot(abs(p$known_discounted_net_cashflows-case$past)<1e-10,abs(p$expected_final_loss-(case$ead-case$past-(case$ead-case$past)*mean_ratio))<1e-7,is.null(r$unidentified_tail$episodes[[1]]$expected_final_lgd),p$unresolved_probability>0,any(grepl('terminal',unlist(p$excluded_cashflows))),abs(r$event_conditioned_loss$expected_loss-expected/2)<1e-10,r$treatment$candidates[[1]]$scenario_difference_from_baseline==3,r$ineligible_treatment$status=='INFEASIBLE');if(product!='COUNTERPARTY_EXPOSURE')stopifnot(r$exposure$schedule[[1]]$conditional_ead==case$ead)}}
 list(data_origin=data$data_origin,version=data$version,product=data$product,variants=out)
}
